import sys


def slow(rows):
    sums = {}
    get = sums.get
    for line in rows:
        if not line:
            continue
        parts = line.split(b',')
        if len(parts) < 3:
            continue
        cat = parts[1]
        sums[cat] = get(cat, 0.0) + float(parts[2])
    return sums


def main():
    data = sys.stdin.buffer.read()
    rows = data.split(b'\n')[1:]
    if rows and rows[-1] == b'':
        rows.pop()
    sums = None
    if rows and b'' not in rows and all(r.count(b',') == 2 for r in rows[:1]):
        pieces = b','.join(rows).split(b',')
        if len(pieces) == 3 * len(rows):
            cats = pieces[1::3]
            sums = {}
            get = sums.get
            for c, v in zip(cats, map(float, pieces[2::3])):
                sums[c] = get(c, 0.0) + v
    if sums is None:
        sums = slow(rows)
    out = []
    for cat in sorted(sums):
        out.append(cat.decode().rstrip('\r') + ',' + ('%.2f' % sums[cat]))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


if __name__ == '__main__':
    main()

import sys
from itertools import compress


def main():
    data = sys.stdin.buffer.read()
    lines = data.split(b'\n')[1:]
    if lines and not lines[-1]:
        lines.pop()
    rows = [l.split(b',') for l in lines]
    if any(len(r) != 3 for r in rows):
        rows = [r for r in rows if len(r) >= 3]
    cats = [r[1] for r in rows]
    vals = list(map(float, [r[2] for r in rows]))
    sums = {}
    get = sums.get
    for c, v in zip(cats, vals):
        sums[c] = get(c, 0.0) + v
    out = []
    for cat in sorted(sums):
        out.append(cat.decode() + ',' + ('%.2f' % sums[cat]))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


if __name__ == '__main__':
    main()
